// Convierte el aviso de WhatsApp en el pedido que entiende el bot.
// Un aviso puede traer estados (entregado, leído) en vez de mensajes: en ese caso no se hace nada.
const aviso = $input.first().json;
const m = aviso.messages?.[0];
if (!m) return [];

let type = 'text';
let text = '';
let media_id = '';
if (m.type === 'text') text = m.text?.body ?? '';
else if (m.type === 'button') text = m.button?.text ?? '';
else if (m.type === 'interactive') text = m.interactive?.button_reply?.title ?? m.interactive?.list_reply?.title ?? '';
else if (m.type === 'image' || m.type === 'document') {
  // Fotos y PDF (por ejemplo, recetas): el bot las descarga de WhatsApp con este id.
  const adjunto = m.image ?? m.document;
  media_id = adjunto?.id ?? '';
  text = adjunto?.caption ?? '';
  type = media_id ? 'media' : 'unsupported';
} else type = 'unsupported'; // audios, ubicación, stickers…

return [{
  json: {
    phone: m.from,
    name: aviso.contacts?.[0]?.profile?.name ?? '',
    type,
    text,
    media_id,
    message_id: m.id,
    phone_number_id: aviso.metadata?.phone_number_id ?? '',
  },
}];

// El bot devuelve uno o más textos; se arma un ítem por texto para enviarlos en orden.
const respuesta = $input.first().json;
const mensaje = $('Armar mensaje').first().json;
if (respuesta.action !== 'reply' || !Array.isArray(respuesta.replies)) return [];

return respuesta.replies.map((text) => ({
  json: { phone: mensaje.phone, phone_number_id: mensaje.phone_number_id, text },
}));
